draw:
var T = p.tension, mu = p.mu / 1000.0;   // slider in g/m
var v = Math.sqrt(T / mu);
var L = 6.0;                              // metres of rope
var tt = L / v;                           // transit time

var padL = 30, padR = 20;
var yMid = H * 0.52;
var sx = (W - padL - padR) / L;

// rope at rest
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(padL, yMid); ctx.lineTo(W - padR, yMid); ctx.stroke();

// a gaussian pulse marching right, restarting after it leaves
var cycle = tt + 0.5;
var now = t % cycle;
var xc = v * now;
var width = 0.45;
var amp = H * 0.24;

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 300; i++) {
  var x = L * i / 300;
  var u = (x - xc) / width;
  var y = yMid - amp * Math.exp(-u * u);
  if (i === 0) ctx.moveTo(padL + x * sx, y); else ctx.lineTo(padL + x * sx, y);
}
ctx.stroke();

// walls
ctx.strokeStyle = C.rule;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(padL, yMid - amp * 1.5); ctx.lineTo(padL, yMid + amp * 0.8); ctx.stroke();
ctx.beginPath(); ctx.moveTo(W - padR, yMid - amp * 1.5); ctx.lineTo(W - padR, yMid + amp * 0.8); ctx.stroke();

// clock bar
var frac = Math.min(now / tt, 1);
ctx.strokeStyle = C.figure;
ctx.lineWidth = 4;
ctx.beginPath();
ctx.moveTo(padL, H - 14);
ctx.lineTo(padL + frac * (W - padL - padR), H - 14);
ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

ctx.fillStyle = C.ink;
ctx.fillText("6.0 m of rope, tension T pulling both ends", padL + 6, 16);
ctx.fillText("elapsed " + Math.min(now, tt).toFixed(3) + " s of " + tt.toFixed(3) + " s", padL + 6, H - 20);

out.note = "v = sqrt(T/mu) = sqrt(" + T.toFixed(0) + " / " + mu.toFixed(4) + ") = "
  + v.toFixed(1) + " m/s, so the pulse crosses 6.0 m in " + tt.toFixed(3) + " s";
